pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(message) = bytes.strip_prefix("v:2|hello|") {
        return Ok(Msg::Hello(message.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat|") {
        return sequence
            .parse::<u32>()
            .map(Msg::Heartbeat)
            .map_err(|_| "unknown".into());
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(message) => format!("v:2|hello|{}", message),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat|{}", sequence),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(super::decode("ping"), Ok(super::Msg::Ping)));
    }

    #[test]
    fn roundtrips_hello_frame() {
        let message = super::Msg::Hello("world".into());
        assert!(matches!(super::decode(&super::encode(&message)), Ok(super::Msg::Hello(value)) if value == "world"));
    }

    #[test]
    fn roundtrips_heartbeat_frame() {
        let message = super::Msg::Heartbeat(42);
        assert!(matches!(super::decode(&super::encode(&message)), Ok(super::Msg::Heartbeat(sequence)) if sequence == 42));
    }
}
